options.helpers:
/* ── 플러그인 API 호환 shim (버전 차이로 조용히 빈 패널이 되는 걸 막는다) ──
   Business Text v6 : new Function('context', code) → context.{handlebars, panelData}
   구버전(v4/v5)     : handlebars / panelData / data 가 **개별 변수**로 들어온다.
   폐쇄망처럼 미러된 구버전이 깔리면 `context` 가 없어 ReferenceError 로 죽고,
   helper 가 등록되지 않아 패널이 **에러 없이 텅** 빈다.
   typeof 가드라 없는 식별자를 참조해도 안전하다. */
var __BTCTX = (typeof context !== 'undefined' && context) ? context : {};
var __BTH = __BTCTX.handlebars || (typeof handlebars !== 'undefined' ? handlebars : null);
var __BTS = (__BTCTX.panelData && __BTCTX.panelData.series)
         || (typeof panelData !== 'undefined' && panelData && panelData.series)
         || (typeof data !== 'undefined' && data && data.series) || [];

/* bt_prelude.js — Business Text 패널 공용 JS 프리앰블.
   각 변형 생성기가 자기 렌더 코드 앞에 이 파일을 통째로 붙인다.

   ── Business Text v6 실행 규약 (소스 실측) ─────────────────────────────
   - 이 코드는 new Function('context', code) 로 실행된다 → 변수명은 context.
   - **반환값은 렌더에 쓰이지 않는다.** 실제 렌더는 content(Handlebars) 가 한다.
     → helper 를 등록하고 content 에서 {{{이름}}} 으로 부른다.
   - renderMode='data' 일 때 context.panelData.series 에 전 refId 프레임이 들어온다.

   ── 살아남는 것 / 죽는 것 (배포된 번들에서 확인) ───────────────────────
     textUtil.sanitize = DOMPurify.sanitize(h, {USE_PROFILES:{html:true},
                                                FORBID_TAGS:["form","input"]})
     살아남음 : table/td/colspan, div, span, button, class, style(inline),
                data-*, flexbox, position:absolute, repeating-linear-gradient
     죽음     : <svg> 전체(html 프로파일에 svg 없음), <script>, on* 핸들러
   → 도형은 전부 CSS 로 그린다. SVG 를 쓰면 조용히 사라진다.

   ── CSS 작성 규칙 (지키지 않으면 패널이 통째로 투명해진다) ─────────────
   1. options.styles 에 :root{} 를 쓰지 말 것 — 문서 전역으로 새어 다른 패널을 망친다.
   2. color-mix()/var() 로 **목업 토큰**을 참조하지 말 것. --panel 같은 건 Grafana 에
      없어서 값이 unresolvable 이 되고, 그러면 그 선언 전체가 무효화된다.
      (배경과 테두리가 둘 다 color-mix 면 타일이 완전 투명해져 "빈 패널" 로 보인다)
      → 리터럴 rgba() 를 쓰거나, var() 는 반드시 폴백과 함께: var(--x, rgba(...))
   3. 인라인 커스텀 프로퍼티(style="--tc:#2a78d6")는 통과한다 — 팀 색은 이 방식으로 넘긴다. */

/* Grafana Vector/배열 양쪽 호환 */
function arr(f) {
  return (f && f.values && f.values.toArray) ? f.values.toArray() : (f ? f.values : []);
}

/* refId 프레임 → { <keyLabel 값>: {라벨..., __v: 값} }

   ⚠ 프레임 형태가 두 가지다 (실측):
     (a) time_series — 시리즈마다 프레임 1개, **라벨이 값 필드(field.labels)에** 붙는다.
         /api/ds/query 백엔드 직접 호출로 확인한 모양이 이것.
     (b) table — 라벨이 컬럼으로 펼쳐진 프레임 1개.
         format:"table" 은 Prometheus **프론트엔드** 데이터소스가 적용하므로
         패널 안에서는 이쪽이 올 수 있다.
   렌더 없이 어느 쪽인지 확정할 수 없어 **둘 다 처리**한다. */
function collectBy(series, refId, keyLabel) {
  const key = keyLabel || "queue";
  const out = {};
  series.filter(s => s.refId === refId).forEach(f => {
    const names = (f.fields || []).map(x => x.name);

    if (names.indexOf(key) >= 0) {                    /* (b) table 형태 */
      const cols = {};
      names.forEach((n, i) => { cols[n] = arr(f.fields[i]); });
      let vn = names.find(n => n === "Value" || n.indexOf("Value") === 0);
      if (!vn) vn = names.find(n => n !== "Time" && f.fields[names.indexOf(n)].type === "number");
      (cols[key] || []).forEach((k, r) => {
        const rec = out[k] || (out[k] = {});
        names.forEach(n => { if (n !== "Time") rec[n] = cols[n][r]; });
        if (vn) rec.__v = cols[vn][r];
      });
      return;
    }

    /* (a) time_series 형태 — 라벨이 값 필드에 */
    const vf = (f.fields || []).find(x => x.type === "number")
            || (f.fields || [])[(f.fields || []).length - 1];
    const lab = (vf && vf.labels) || {};
    if (lab[key] == null) return;
    const rec = out[lab[key]] || (out[lab[key]] = {});
    Object.keys(lab).forEach(k => { rec[k] = lab[k]; });
    const vs = arr(vf);
    rec.__v = vs.length ? vs[vs.length - 1] : null;
  });
  return out;
}
function collect(series, refId) { return collectBy(series, refId, "queue"); }

/* {키: 레코드} → {키: 값} */
function val(m) { const o = {}; Object.keys(m).forEach(k => { o[k] = m[k].__v; }); return o; }

/* 라벨 없는 스칼라 (cluster:shared_pool_vcores 등) */
function scalarOf(series, refId) {
  const f = series.filter(s => s.refId === refId)[0];
  if (!f) return null;
  const vf = (f.fields || []).find(x => x.type === "number")
          || (f.fields || [])[(f.fields || []).length - 1];
  const vs = arr(vf);
  return (vs && vs.length) ? vs[vs.length - 1] : null;
}

/* ── 서식 ──────────────────────────────────────────────────────────── */
const fmt = (v, d) => (v == null || isNaN(v)) ? "—"
  : Number(v).toLocaleString("ko-KR", { minimumFractionDigits: d || 0, maximumFractionDigits: d || 0 });
const pct = (a, b) => (b && a != null && !isNaN(a)) ? a / b * 100 : null;
const esc = (s) => String(s == null ? "" : s)
  .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

/* ── 상태 판정 ─────────────────────────────────────────────────────────
   임계는 목업과 동일: 75 주의 / 90 임박 / 100 초과.

   ⚠ "관측 없음"과 "0%" 를 반드시 구분한다.
   현재 6개 큐 중 4개는 queue:used_* 시리즈가 **아예 없다**(0 이 아니라 부재).
   zero-fill 로 0 을 채워 넣고 그냥 그리면 "여유(초록)" 로 렌더되는데, 이건
   유휴가 아니라 미관측이다 — 관측 못 하는 큐를 건강하다고 단언하게 된다.
   그래서 값이 null 이면 별도 'none' 상태로 회색 처리한다. */
function stat(p) {
  if (p == null || isNaN(p)) return ["none", "관측 없음"];
  if (p >= 100) return ["crit", "초과"];
  if (p >= 90)  return ["ser", "임박"];
  if (p >= 75)  return ["warn", "주의"];
  return ["ok", "여유"];
}

/* ── 빈 패널 진단 ──────────────────────────────────────────────────────
   쿼리는 통과했는데 화면이 비는 경우가 이 패널의 대표 실패 모드다.
   헤드리스 브라우저를 못 띄우는 환경이라 API 검증으로는 절대 안 잡힌다.
   → 렌더할 게 없으면 프레임 구조를 화면에 출력해 원인을 눈으로 볼 수 있게 한다.
   각 변형은 데이터가 비면 반드시 bail(...) 후 return 할 것. */
function bail(H, helperName, S, why) {
  const dump = (S || []).map(s => {
    const names = (s.fields || []).map(f => f.name).join("/");
    return esc(s.refId) + "[" + names + "]";
  }).join(" · ");
  H.registerHelper(helperName, () => new H.SafeString(
    '<div style="padding:14px;line-height:1.7;font-size:12px;opacity:.8">'
    + '<b>데이터 없음</b> — ' + esc(why) + '<br>'
    + 'frames=' + (S || []).length + '<br>'
    + (dump || '(프레임 없음)')
    + '</div>'));
}

/* 공용 팔레트 — 목업 _SPEC.md 와 동일 */
const COLORS = {
  "AI/Data Platform": "#2a78d6", "품질 지능화": "#eb6834",
  "EES/MDM/IPA": "#1baf7a", "장비 지능화": "#eda100"
};
const ORDER = ["root.platform", "root.fdc", "root.smartbig", "root.yms", "root.tttm", "root.pluto"];
const TEAM_ORDER = ["AI/Data Platform", "품질 지능화", "EES/MDM/IPA", "장비 지능화"];

const H = __BTH;
const S = __BTS;

/* ⚠ 원래 레코딩 룰(queue:info)에 있던 값. 출처가 되는 메트릭이 없어서
   (엑셀 배분표에만 있음) 룰을 안 쓰면 여기에 옮겨 적어야 한다.
   대시보드가 늘어나면 이 블록도 그만큼 복제된다. */
const INFO = {
  "root.platform": {service:"PLATFORM", service_ko:"플랫폼 운영 관리", team:"AI/Data Platform",
    ldap:"platform", ns_app:"app-platform", ns_sql:"sql-platform", sql_engine:"O",
    catalog:"all", bucket:"ic-platform", workload:"플랫폼 공유"},
  "root.fdc": {service:"FDC", service_ko:"FDC 서비스", team:"AI/Data Platform",
    ldap:"fdc", ns_app:"app-fdc", ns_sql:"-", sql_engine:"X",
    catalog:"", bucket:"fdc, ic-lfdc, ic-m…", workload:"lfd/fdc"},
  "root.smartbig": {service:"SMARTBIG", service_ko:"Smart Big 서비스", team:"품질 지능화",
    ldap:"smartbig", ns_app:"app-smartbig", ns_sql:"sql-smartbig", sql_engine:"O",
    catalog:"icberg, icnfa, smartbig, tas, pntchp", bucket:"smartbig, ic-ees, ic-s…", workload:"canal/oed/wfbm/ti…"},
  "root.yms": {service:"YMS", service_ko:"Smart YMS 서비스", team:"품질 지능화",
    ldap:"yms", ns_app:"app-yms", ns_sql:"-", sql_engine:"O",
    catalog:"(SMARTBIG 과 병합)", bucket:"ic-bmc, ic-wt, i…", workload:"omc/tsv/wt/pnt/tas…"},
  "root.tttm": {service:"TTTM", service_ko:"-", team:"EES/MDM/IPA",
    ldap:"tttm", ns_app:"app-tttm", ns_sql:"sql-tttm", sql_engine:"O",
    catalog:"icberg", bucket:"ic-tttm", workload:"tttm"},
  "root.pluto": {service:"PLUTO", service_ko:"-", team:"장비 지능화",
    ldap:"pluto", ns_app:"app-pluto", ns_sql:"sql-pluto", sql_engine:"O",
    catalog:"icberg", bucket:"ic-pluto", workload:"pluto"},
};
const SRC_LEGEND = "<div class=\"srcleg\"><span class=\"it\"><span class=\"src doc\">\ubb38\uc11c</span> <b>\ud558\ub4dc\ucf54\ub529</b> \u2014 \uc6d0\ubcf8 \ubc30\ubd84\ud45c(<code>team-dashboard.md</code>) \uc804\uc0ac\uac12. \ucd9c\ucc98 \uba54\ud2b8\ub9ad\uc774 \uc5c6\uc5b4 \uc0ac\ub78c\uc774 \uc62e\uaca8 \uc801\uc5c8\ub2e4. \uc870\ud68c \uc2dc\uc810\uacfc \ubb34\uad00\ud558\uac8c \ud56d\uc0c1 \uac19\uc740 \uac12\uc774\uba70, \uc2e4\uc81c \ud074\ub7ec\uc2a4\ud130 \uc124\uc815\uacfc \uc5b4\uae0b\ub098 \uc788\uc5b4\ub3c4 \ud654\uba74\uc740 \uadf8\ub300\ub85c\ub2e4.</span><span class=\"it\"><span class=\"src live\">\uc2e4\uce21</span> <b>PromQL \uc870\ud68c\uac12</b> \u2014 <code>yunikorn_queue_resource</code> / <code>yunikorn_queue_app</code> / <code>minio_cluster_usage_buckets_total_bytes</code> \ub97c \ub300\uc2dc\ubcf4\ub4dc \uc2dc\uac04\ubc94\uc704\ub85c \uc870\ud68c\ud574 \uacc4\uc0b0. <span class=\"src na\">\ubbf8\uae30\uc7ac</span> \ub294 \uc6d0\ubcf8 \ud45c\uc5d0 \ud589\ub9cc \uc788\uace0 \uac12\uc774 \ube44\uc5b4 \uc788\ub294 \ud56d\ubaa9\uc774\ub2e4.</span><span class=\"it\">\u26a0 <b>\ubb38\uc11c \ubcf4\uc7a5\uc790\uc6d0\uacfc \uc2e4\uce21 \ubcf4\uc7a5(guaranteed)\uc740 \uc11c\ub85c \ub2e4\ub978 \uc218\ub2e4.</b> \ubb38\uc11c\ub294 \ubc30\ubd84 \uacc4\ud68d(\ud569 10,840 vCores), \uc2e4\uce21\uc740 \uc774 \ub7a9 YuniKorn \ud050\uc5d0 \uc2e4\uc81c\ub85c \uac78\ub9b0 \uac12\uc774\ub2e4 \u2014 \uc0ac\uc6a9\ub960\u00b7\uc0c1\ud0dc \ud310\uc815\uc740 \uc804\ubd80 <b>\uc2e4\uce21</b> \uae30\uc900\uc774\ub2e4.</span></div>";
const SRC_GROUPS = "<tr class=\"srcgrp\"><th class=\"srcgrp-doc\" colspan=\"2\"><span class=\"src doc\">\ubb38\uc11c</span> \ud300\u00b7\uc11c\ube44\uc2a4 \ub9e4\ud551 \u00b7 \ud558\ub4dc\ucf54\ub529</th><th class=\"srcgrp-live\" colspan=\"7\"><span class=\"src live\">\uc2e4\uce21</span> PromQL \uc2e4\uce21 \u2014 yunikorn_*</th></tr>";

const info = INFO;
const tq = val(collectBy(S,"tq","team")),  tu = val(collectBy(S,"tu","team"));
const tmq = val(collectBy(S,"tmq","team")), tmu = val(collectBy(S,"tmu","team"));
const teams = TEAM_ORDER.filter(x => tq[x] != null);
if (!teams.length) { bail(H,'summary',S,'team:quota_vcores 가 비었습니다.'); return; }
const total = teams.reduce((a,x) => a + (tq[x]||0), 0);

/* 팀별 서비스 목록 — 네이티브 table 은 여러 값을 한 칸에 못 이어 붙인다 */
const svcOf = {};
ORDER.filter(q => info[q]).forEach(q => {
  (svcOf[info[q].team] = svcOf[info[q].team] || []).push(info[q].service);
});

function cell(p, tc){
  const st = stat(p);
  return '<td><span class="pbar" style="--tc:' + tc + '"><i style="width:'
    + (p==null?0:Math.min(100,p)).toFixed(2) + '%"></i></span>'
    + (p==null ? '<span class="nd">—</span>' : '<b>'+fmt(p,0)+'%</b>') + '</td>';
}

let h = '<div class="hd">팀별 자원 사용 요약<em>CPU vCores · Memory GiB</em></div>';
h += '<table class="tb"><thead>' + SRC_GROUPS + '<tr>'
   + '<th class="l">팀</th><th class="l">서비스</th><th>보장 VCORES</th><th>비중</th>'
   + '<th>CPU 사용</th><th>CPU %</th><th>MEM 사용(GIB)</th><th>MEM %</th><th>상태</th>'
   + '</tr></thead><tbody>';
teams.forEach(x => {
  const tc = COLORS[x] || '#8a93a3';
  const cr = pct(tu[x], tq[x]);
  const mu = tmu[x]==null?null:tmu[x]/1073741824, mq = tmq[x]==null?null:tmq[x]/1073741824;
  const mr = pct(mu, mq);
  const worst = (cr==null && mr==null) ? null : Math.max(cr==null?-1:cr, mr==null?-1:mr);
  const st = stat(worst<0 ? null : worst);
  h += '<tr><td class="l"><span class="nm"><i class="dot" style="background:'+tc+'"></i>'
     + esc(x) + '</span></td>'
     + '<td class="l sub">' + esc((svcOf[x]||[]).join(', ')) + '</td>'
     + '<td><b>' + fmt(tq[x],2) + '</b></td>'
     + '<td>' + fmt(tq[x]/total*100,1) + '%</td>'
     + '<td>' + (tu[x]==null ? '<span class="nd">관측 없음</span>' : fmt(tu[x],2)) + '</td>'
     + cell(cr, tc)
     + '<td>' + (mu==null ? '<span class="nd">관측 없음</span>' : fmt(mu,1)) + '</td>'
     + cell(mr, tc)
     + '<td><span class="chip ' + st[0] + '">' + st[1] + '</span></td></tr>';
});
h += '</tbody></table>' + SRC_LEGEND;
H.registerHelper('summary', () => new H.SafeString(h));

