     + '<td class="vcell">' + (uu==null ? '<span class="nd">관측 없음</span>' : '<b>'+fmt(uu,DEC)+'</b>')
     + ' <span class="sl">/ ' + fmt(qq,DEC) + '</span></td></tr>';
