/* ── 상태 판정 ─────────────────────────────────────────────────────────
   임계는 목업과 동일: 75 주의 / 90 임박 / 100 초과.

   ⚠ "관측 없음"과 "0%" 를 반드시 구분한다.
   현재 6개 큐 중 4개는 queue:used_* 시리즈가 **아예 없다**(0 이 아니라 부재).
   zero-fill 로 0 을 채워 넣고 그냥 그리면 "여유(초록)" 로 렌더되는데, 이건
   유휴가 아니라 미관측이다 — 관측 못 하는 큐를 건강하다고 단언하게 된다.
   그래서 값이 null 이면 별도 'none' 상태로 회색 처리한다. */
function stat(p) {
  if (p == null || isNaN(p)) return ["none", "관측 없음"];
  if (p >= 100) return ["crit", "초과"];
  if (p >= 90)  return ["ser", "임박"];
  if (p >= 75)  return ["warn", "주의"];
  return ["ok", "여유"];
}

/* ── 빈 패널 진단 ──────────────────────────────────────────────────────
   쿼리는 통과했는데 화면이 비는 경우가 이 패널의 대표 실패 모드다.
   헤드리스 브라우저를 못 띄우는 환경이라 API 검증으로는 절대 안 잡힌다.
   → 렌더할 게 없으면 프레임 구조를 화면에 출력해 원인을 눈으로 볼 수 있게 한다.
   각 변형은 데이터가 비면 반드시 bail(...) 후 return 할 것. */
function bail(H, helperName, S, why) {
  const dump = (S || []).map(s => {
    const names = (s.fields || []).map(f => f.name).join("/");
    return esc(s.refId) + "[" + names + "]";
  }).join(" · ");
  H.registerHelper(helperName, () => new H.SafeString(
    '<div style="padding:14px;line-height:1.7;font-size:12px;opacity:.8">'
    + '<b>데이터 없음</b> — ' + esc(why) + '<br>'
    + 'frames=' + (S || []).length + '<br>'
    + (dump || '(프레임 없음)')
    + '</div>'));
}

/* 공용 팔레트 — 목업 _SPEC.md 와 동일 */
const COLORS = {
  "AI/Data Platform": "#2a78d6", "품질 지능화": "#eb6834",
  "EES/MDM/IPA": "#1baf7a", "장비 지능화": "#eda100"
};
const ORDER = ["root.platform", "root.fdc", "root.smartbig", "root.yms", "root.tttm", "root.pluto"];
const TEAM_ORDER = ["AI/Data Platform", "품질 지능화", "EES/MDM/IPA", "장비 지능화"];

const H = __BTH;
const S = __BTS;

const q = val(collectBy(S,"q","team")), u = val(collectBy(S,"u","team"));
const teams = TEAM_ORDER.filter(x => q[x] != null);
if (!teams.length) { bail(H,'mem',S,'쿼터 시리즈가 비었습니다.'); return; }
const DIV = 1073741824, DEC = 1, UNIT = "GiB";
const axis = Math.max.apply(null, teams.map(x => (q[x]||0)/DIV)) * 1.25;

let h = '<div class="hd">Memory 사용률<em>YuniKorn 큐 쿼터 대비 % · 룰 미사용</em></div><table class="tb">';
teams.forEach(x => {
  const qq = q[x]/DIV, uu = u[x]==null ? null : u[x]/DIV;
  const inb = uu==null ? 0 : Math.min(uu,qq)/axis*100;
  const ovr = uu==null ? 0 : Math.max(0,uu-qq)/axis*100;
  h += '<tr><td class="l nmcell"><span class="dot" style="background:' + COLORS[x] + '"></span>'
     + esc(x) + '</td>'
     + '<td class="barcell"><div class="trk" style="--tc:' + COLORS[x] + '">'
     + (uu==null ? '' : '<i class="base" style="width:' + inb.toFixed(2) + '%"></i>')
     + (ovr>0 ? '<i class="ovr" style="left:' + inb.toFixed(2) + '%;width:' + ovr.toFixed(2) + '%"></i>' : '')
     + '<u style="left:' + (qq/axis*100).toFixed(2) + '%"></u></div></td>'
     + '<td class="vcell">' + (uu==null ? '<span class="nd">관측 없음</span>' : '<b>'+fmt(uu,DEC)+'</b>')
     + ' <span class="sl">/ ' + fmt(qq,DEC) + '</span></td></tr>';
});
h += '</table>';
H.registerHelper('mem', () => new H.SafeString(h));

options.styles:
.chip{font-size:10.5px;font-weight:700;padding:2px 8px;border-radius:4px;white-space:nowrap;
      border:1px solid rgba(128,138,155,.35)}
.chip.ok{color:#0ca30c}.chip.warn{color:#8a6200}.chip.ser{color:#ec835a}
.chip.crit{color:#d03b3b}.chip.none{color:#8a93a3}
.dot{width:9px;height:9px;border-radius:2px;flex:none;display:inline-block}
.tb{width:100%;border-collapse:collapse;font-size:12px}
.tb th{text-align:right;font-size:10px;letter-spacing:.06em;font-weight:700;opacity:.5;
       padding:0 8px 7px;border-bottom:1px solid rgba(128,138,155,.28);white-space:nowrap}
.tb th.l{text-align:left}
.tb td{padding:9px 8px;border-bottom:1px solid rgba(128,138,155,.16);text-align:right;
       font-variant-numeric:tabular-nums;white-space:nowrap}
.tb td.l{text-align:left}
.tb tr:last-child td{border-bottom:none}
.nm{display:flex;align-items:center;gap:8px;font-weight:650}
.sub{opacity:.55;font-weight:400;font-size:11px}
.code{font-family:monospace;font-size:10.5px;padding:2px 7px;border-radius:4px;
      background:rgba(128,138,155,.16)}
.pbar{position:relative;display:inline-block;width:62px;height:6px;border-radius:3px;
      background:rgba(128,138,155,.20);vertical-align:middle;margin-right:7px}
.pbar i{position:absolute;left:0;top:0;bottom:0;border-radius:3px;background:var(--tc,#8a93a3)}
.hd{font-size:13px;font-weight:700;margin-bottom:2px}
.hd em{font-style:normal;font-size:11px;font-weight:400;opacity:.55;margin-left:7px}

.nmcell{width:170px}.nmcell .dot{margin-right:8px;vertical-align:middle}
