targets.expr:
sum by (queue) (max by (cluster,queue) (
label_replace(
  yunikorn_queue_app{cluster="$cluster", state="running", queue!="root"},
  "queue", "root.$1", "queue", "^(?:root\\.)?(.+)$"
)
))
